// Generated by gen-roster-data.mjs — do not edit. Re-run `npm run roster:data`.
// Lazy per-faction roster data. Each faction file is a chunk of its own so the roster
// editor only pulls the faction being built (PWA entry-chunk stays clean — see CLAUDE.md).
// Glob only the faction files — exclude core/items/index and the test file (the latter pulls
// in node: builtins and would break the browser build once this loader is bundled).
const loaders = import.meta.glob(['./*.js', '!./core.js', '!./items.js', '!./index.js', '!./*.test.js'], { import: 'default' })

const load = (slug) => {
  const loader = loaders[`./${slug}.js`]
  return loader ? loader() : Promise.resolve(null)
}

// Load a faction's roster data, folding the shared Adeptus Astartes pool into an SM Chapter
// (data.sharedUnitIds → space-marines units), so callers see one flat unit list. Folded units
// keep their own ids and resolve against the shared items/texts dicts (see ./items.js).
//
// A shared unit can cost this Chapter something else than it costs the Codex (Blood Angels' Assault
// Intercessor Squad, every Chapter's Repulsor Executioner) — data.unitPoints carries those, keyed
// by unit id and then by MODEL COUNT, and only where they differ. Same mechanism, same source and
// the same numbers as pointsOverrides in src/data/datasheets/<chapter>.js, so a unit is priced
// identically here and on its datasheet page.
const repriced = (unit, byModels) => {
  if (!byModels) return unit
  const sizes = unit.sizes.map((s) => {
    const pts = byModels[s.per[1]] ?? byModels[s.per[0]]
    return pts == null || pts === s.pts ? s : { ...s, pts }
  })
  return sizes.some((s, i) => s !== unit.sizes[i]) ? { ...unit, sizes } : unit
}

// Units this army may ally in (data.allies — see the generator's Allies section). A group's ids
// are NAMESPACED `<source slug>:<unit id>` when the units live in another faction's bundle, and
// bare when they are already in this one (Blood Legions in world-eaters.js). So the merge only has
// to look at the namespaced ones: load each source bundle once, take the units the group names,
// and keep the namespaced id as the unit's id — that id is what a roster entry stores, what tells
// two same-named datasheets apart (Astra Militarum and Imperial Agents each have a Ministorum
// Priest) and what says which faction's datasheet page the unit links to.
//
// Allies are opt-in because they cost extra chunks: an IMPERIUM army can reach three source
// bundles it otherwise never loads. The editor asks for them (anything may be added); the
// read-only screens ask only when the list actually holds one (rosterEngine's `usesAllies`).
async function allyUnits(data) {
  const need = new Map()     // source slug -> Set(unit id)
  const prices = new Map()   // namespaced id -> { models: points }
  for (const g of data.allies || []) {
    for (const id of g.ids || []) {
      const at = id.indexOf(':')
      if (at < 0) continue   // already in this bundle
      const src = id.slice(0, at)
      if (!need.has(src)) need.set(src, new Set())
      need.get(src).add(id.slice(at + 1))
      if (g.up?.[id]) prices.set(id, g.up[id])
    }
  }
  const out = []
  for (const [src, ids] of need) {
    const bundle = await load(src)
    for (const u of bundle?.units || []) {
      if (!ids.has(u.id)) continue
      const id = `${src}:${u.id}`
      // `leads` names units of the SAME bundle by their bare ids, which this merge has just
      // namespaced — left as they are, an allied leader could lead nothing (Watch Captain Artemis
      // offered no Aquila Kill Team in a Grey Knights list, a player's report of 2026-10-01).
      const leads = u.leads?.map((l) => ({ ...l, to: `${src}:${l.to}` }))
      out.push({ ...repriced(u, prices.get(id)), id, ...(leads && { leads }) })
    }
  }
  return out
}

export async function loadRosterFaction(slug, { allies = false } = {}) {
  const raw = await load(slug)
  if (!raw) return null
  // A detachment printed in this faction's book for OTHER armies (`lend`) is not one of its own:
  // the armies it is lent to fold it in below (Deathwatch Support).
  const data = raw.detachments?.some((d) => d.lend) ? { ...raw, detachments: raw.detachments.filter((d) => !d.lend) } : raw
  const extra = allies && data.allies?.length ? await allyUnits(data) : []
  // A shared detachment comes from space-marines.js unless `sharedDetachmentFrom` names its
  // bundle (Deathwatch Support → deathwatch.js).
  const fromOf = (name) => data.sharedDetachmentFrom?.[name] || 'space-marines'
  const needSm = !!(data.sharedUnitIds?.length || data.sharedDetachments?.some((n) => fromOf(n) === 'space-marines'))
  if (!needSm && !data.sharedDetachments?.length && !extra.length) return data
  const sm = needSm ? await load('space-marines') : null
  const idSet = new Set(data.sharedUnitIds || [])
  const shared = (sm?.units || [])
    .filter((u) => idSet.has(u.id))
    .map((u) => ({ ...repriced(u, data.unitPoints?.[u.id]), shared: 1 }))
  const units = [...data.units, ...shared, ...extra].sort((a, b) => a.name.localeCompare(b.name))
  // …and the Codex detachments this Chapter may field, which live in space-marines.js for the
  // same reason its shared units do. A different Detachment Points cost for this Chapter comes
  // with them (`detachmentDp`), so the budget the editor spends is the Chapter's own.
  if (!data.sharedDetachments?.length) return { ...data, units }
  const bySource = new Map()
  for (const n of data.sharedDetachments) {
    const src = fromOf(n)
    if (!bySource.has(src)) bySource.set(src, new Set())
    bySource.get(src).add(n)
  }
  // The army's own come first and the others after them, a group per faction they come from
  // (`from`, the slug the pickers head the group with — DetachmentGroupHead), each by name.
  const byName = (a, b) => a.name.localeCompare(b.name)
  const dets = []
  for (const [src, want] of bySource) {
    const bundle = src === 'space-marines' ? sm : await load(src)
    const group = []
    for (const d of bundle?.detachments || []) {
      if (!want.has(d.name)) continue
      const { lend, ...det } = d
      group.push({ ...det, dp: data.detachmentDp?.[d.name] ?? d.dp, shared: 1, from: src })
    }
    dets.push(...group.sort(byName))
  }
  const detachments = [...[...data.detachments].sort(byName), ...dets]
  return { ...data, units, detachments }
}

export { default as rosterCore } from './core.js'
export { default as rosterItems } from './items.js'
